const intro=document.createElement('section');intro.id='intro';intro.innerHTML='<p class="eyebrow">A little something just for you</p><h1 class="intro-title">For Oswuy, with love</h1><button class="envelope" aria-label="Open your birthday envelope and play music"></button><p class="hint">Tap the envelope to open ♡</p>';document.body.append(intro);
const main=document.querySelector('main');main.inert=true;
main.innerHTML=`<div class="art-crop hero-art"><img src="birthday.png" alt="Happy birthday Oswuy! Birthday VIP" width="1024" height="1536"></div>
<section class="wish-section" aria-labelledby="wish-title"><div class="wish-copy"><p class="eyebrow">A moment just for you</p><h2 id="wish-title">Make a<br>Wish <span>✧</span></h2><p class="section-note">Close your eyes. Wish for something beautiful.</p></div><div class="cake-side"><div class="live-cake" role="img" aria-label="Birthday cake with three lit candles"><div class="candles">${[0,1,2].map(i=>`<div class="candle" style="--delay:${i*100}ms"><span class="live-flame"></span><span class="wick"></span><span class="wax"></span><span class="smoke"></span></div>`).join('')}</div><svg viewBox="0 0 280 145" aria-hidden="true"><ellipse cx="140" cy="126" rx="124" ry="12"/><path d="M35 42 Q140 12 245 42 L245 116 Q140 139 35 116Z"/><path d="M35 42 Q48 29 60 39 Q76 26 91 36 Q107 24 122 34 Q140 23 157 34 Q175 25 190 36 Q207 28 221 39 Q235 31 245 42 L245 62 Q230 86 215 61 Q201 86 184 64 Q166 91 148 65 Q130 88 113 64 Q96 87 80 63 Q63 86 49 61 Q40 72 35 62Z"/><path d="M36 91 Q60 110 82 92 Q106 111 130 94 Q154 113 177 94 Q202 109 244 91M36 113 Q140 136 244 113"/></svg></div><button class="action-button" id="blow">Make a wish & blow ♡</button><p id="status" role="status">Three candles. One beautiful wish.</p></div></section>
<section class="real-letter" id="letter"><span class="letter-icon" aria-hidden="true">♡</span><h2>A Little Letter for You</h2><p>Heyy!! Happy birthday I hope you had fun yesterday and I hope today goes just as you planned may you always be filled with positive surrounding and people that love and care about you I wish you nothing but the best today and always, I love youuuu!</p><p>may you always carry that spark in you, super happy we met !</p><p>p.s. lmk when ur free so we can plan something and i can give you ur gift!!!</p><div class="letter-signature" aria-label="from Brittanys"><span class="signature-from">from</span><span class="signature-name">Brittanys<span class="signature-heart" aria-hidden="true">♡</span></span><svg class="signature-flourish" viewBox="0 0 240 30" aria-hidden="true"><path d="M8 24C48 8 129 4 195 13S232 12 225 5M189 20L204 17"/></svg></div></section>
<section class="surprise-section"><div><p class="eyebrow">One more little thing</p><h2>A Birthday<br>Surprise</h2></div><div class="gift-side"><svg class="neon-gift" viewBox="0 0 200 190" aria-hidden="true"><path d="M30 80L170 80 162 169 39 169ZM23 66H177V87H23ZM90 67V169M111 67V169M100 65C15 64 30-8 73 23L100 65C159-8 199 36 100 65ZM100 66L56 111M100 66L143 111"/></svg><button class="action-button" id="surprise">Unwrap your surprise ✧</button></div></section><footer class="birthday-footer">HERE’S TO YOU ♡</footer>`;
const sound=document.createElement('button');sound.id='sound';sound.className='visible-action';sound.textContent='♫ Music off';sound.setAttribute('aria-pressed','false');document.body.append(sound);
const audio = new Audio('bday.mp3');audio.loop=true;audio.preload='none';audio.volume=.55;
function musicState(){const playing=!audio.paused&&!audio.error;sound.textContent=playing?'♫ Music on':'♫ Music off';sound.setAttribute('aria-pressed',String(playing))}
audio.addEventListener('play',musicState);audio.addEventListener('pause',musicState);audio.addEventListener('error',musicState);
async function playMusic(){try{await audio.play()}catch{audio.pause()}musicState()}
intro.querySelector('button').onclick=()=>{document.body.classList.add('opened');main.inert=false;playMusic();burst();document.querySelector('#blow').focus({preventScroll:true})};
sound.onclick=()=>{if(audio.paused)playMusic();else audio.pause()};
function burst(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;for(let i=0;i<65;i++){const s=document.createElement('span');s.className='spark';s.textContent=['✦','♡','✧'][i%3];s.style.cssText=`left:${Math.random()*100}vw;top:${Math.random()*50}vh;--x:${Math.random()*240-120}px;animation-delay:${Math.random()*.7}s`;document.body.append(s);setTimeout(()=>s.remove(),3500)}}
let blown=false,blowing=false;function blow(){if(blowing)return;const button=document.querySelector('#blow');if(blown){blown=false;main.classList.remove('blown','blowing');button.textContent='Make a wish & blow ♡';document.querySelector('#status').textContent='Another wish? There’s always room for more.';document.querySelector('.live-cake').setAttribute('aria-label','Birthday cake with three lit candles');return}blowing=true;button.disabled=true;button.textContent='Sending your wish…';main.classList.add('blowing');setTimeout(()=>{main.classList.add('blown');main.classList.remove('blowing');blown=true;document.querySelector('.live-cake').setAttribute('aria-label','Birthday cake with extinguished candles');document.querySelector('#status').textContent='Your wish is on its way, Oswuy. ♡';button.textContent='Light the candles again ✧';button.disabled=false;blowing=false},1100)}
document.querySelector('#blow').onclick=blow;
function surprise(){modal.classList.add('starbucks-surprise');document.querySelector('#heading').textContent='A little treat for you ♡';const copy=document.querySelector('#copy');copy.replaceChildren();const card=document.createElement('div');card.className='starbucks-card';const gift=window.BIRTHDAY_GIFT||{};if(gift.image){const img=document.createElement('img');img.src=gift.image;img.alt='Your Starbucks birthday gift card';card.append(img)}else{const brand=document.createElement('strong');brand.textContent='STARBUCKS';const star=document.createElement('span');star.textContent='✦';const note=document.createElement('p');note.textContent='A birthday coffee, with love.';card.append(brand,star,note)}copy.append(card);if(gift.url){const link=document.createElement('a');link.className='action-button gift-link';link.href=gift.url;link.target='_blank';link.rel='noopener noreferrer';link.textContent='Open your gift card';copy.append(link)}else{const pending=document.createElement('p');pending.className='gift-pending';pending.textContent='Your gift card is on its way ♡';copy.append(pending)}modal.showModal();burst()}
document.querySelector('#surprise').onclick=surprise;modal.addEventListener('close',()=>modal.classList.remove('surprise','starbucks-surprise'));
for(let i=0;i<16;i++){const star=document.createElement('span');star.className='ambient';star.setAttribute('aria-hidden','true');star.textContent='✧';star.style.cssText=`left:${Math.random()*100}%;top:${Math.random()*100}%;animation-delay:-${Math.random()*6}s;font-size:${10+Math.random()*15}px`;document.body.append(star)}


